          3,
          reason: 'build-ios + submit-ios + build-macos',
        );
        for (final script in scripts) {
          // The old path skipped the fresh entry (warning-only) and the
          // trailing `rm -rf "$CLONE_TARGET"` then DELETED it — the
          // workspace silently kept the stale leftover at that repo path.
          expect(
            script,
            contains(r'mv "$GITHUB_WORKSPACE/$name" "$STALE'),
            reason:
                'on a stub collision the stale leftover must move into the '
                '\$STALE sidecar — not stay in the workspace while the '
                'fresh checkout entry is dropped and deleted (gh-1600 '
                'rework: fresh content always wins)',
          );
          expect(
            script.indexOf(r'mv "$GITHUB_WORKSPACE/$name"'),
            lessThan(script.indexOf(r'mv "$entry" "$GITHUB_WORKSPACE/"')),
            reason:
                'the stale stub must be parked BEFORE the fresh entry moves '
                'in — same-name mv would otherwise overwrite the fresh '
                'content (gh-1600 rework)',
          );
          expect(
            script,
            contains('stub collision on'),
            reason:
                'the skip-with-warning path may remain only as the '
                'last-resort fallback when even parking the stub fails '
                '(gh-1600 rework)',
          );
        }
      },
    );

    test(
      'old stale-workspace-* sidecars are pruned before a new one is parked',
      () {
        final scripts = allCheckoutScripts();
        expect(
          scripts.length,
          3,
          reason: 'build-ios + submit-ios + build-macos',
        );
        for (final script in scripts) {
          expect(
            script,
            contains(r'rm -rf "${RUNNER_TEMP:-/tmp}"/stale-workspace-*'),
            reason:
                'on the persistent box the runner\'s own _temp cleanup '
                'cannot remove mount-held sidecars either — every degraded '
                'checkout must first best-effort-prune previous '
                '`stale-workspace-*` dirs (the containers that held them '
                'may have died since, so the retry often succeeds) '
                '(gh-1600 rework)',
          );
          expect(
            script.indexOf('stale-workspace-*'),
            lessThan(script.indexOf(r'stale-workspace-$(date')),
            reason:
                'the prune must run BEFORE the new timestamped sidecar is '
                'created — otherwise the glob would also match (and '
                're-delete) the fresh dir (gh-1600 rework)',
          );
        }
      },
    );
  });
}

// Issue #1280 — the CLI arch matrix must gate merges and every produced
// binary must boot:
//
// v1.0.512 shipped without fa-linux-arm64/-linux-x64/windows + SHA256SUMS.
// Chain: a flaky PTY boot timeout reds the arm integration leg on the
// release run -> quality-gate red -> the release `binaries` matrix skips
// (ci.yml gates it on `needs.quality-gate.result == 'success'`). The
// never-again gap that made this a merge-gate blind spot: PR validation
// runs are dispatched by Machine SM as `workflow_dispatch` on the PR head,
// but binaries-pr/binaries-smoke-gate gated themselves on
// `github.event_name == 'pull_request'` — the required "Binaries smoke
// gate" context went green-by-skip on every real validation run, so a
// broken arch build could never block a merge. And the release `binaries`
// job uploaded assets without ever booting them (NG2).
//
// Structural lint over .github/workflows/ci.yml (same style as
// dispatch_watch_test.dart / release_hygiene_test.dart).
import 'dart:io';

import 'package:test/test.dart';
import 'package:yaml/yaml.dart';

String read(String path) => File(path).readAsStringSync();
YamlMap jobsOf(String workflowPath) =>
    loadYaml(read(workflowPath))['jobs'] as YamlMap;

/// The full CLI binary target inventory (NG1): every supported target the
/// release ships must exist as a matrix leg in BOTH the merge-gate matrix
/// and the release matrix.
const expectedArchLegs = {
  'windows-x64',
  'macos-arm64',
  'macos-x64',
  'linux-x64',
  'linux-arm64',
};

Set<String> matrixLegs(YamlMap job) {
  final include = (job['strategy'] as YamlMap)['matrix'] as YamlMap;
  return (include['include'] as YamlList)
      .map((e) => '${(e as YamlMap)['os']}-${e['arch']}')
      .toSet();
}

int _stepIndex(YamlMap job, String stepName) => (job['steps'] as YamlList)
    .indexWhere((s) => (s as YamlMap)['name'] == stepName);

void main() {
  final ci = jobsOf('.github/workflows/ci.yml');

  group('NG1 — the arch matrix gates the merge (#1280)', () {
    test('binaries-pr also fires on the SM validation dispatch event', () {
      final cond = (ci['binaries-pr'] as YamlMap)['if'].toString();
      expect(cond, contains("github.event_name == 'pull_request'"));
      expect(
        cond,
        contains("github.event_name == 'workflow_dispatch'"),
        reason:
            'SM-dispatched PR validations are workflow_dispatch — a '
            'pull_request-only gate skipped the required "Binaries smoke '
            'gate" context green on every real validation run '
            '(v1.0.512 starvation class)',
      );
