      'binaries-smoke-gate aggregates the same events (no green-by-skip)',
      () {
        final cond = (ci['binaries-smoke-gate'] as YamlMap)['if'].toString();
        expect(cond, contains("github.event_name == 'workflow_dispatch'"));
      },
    );

